/* vi-style UTF-8 editor, a protected EL0 program using only JKOROS syscalls. */
#include "호출.h"
#include "파일규약.h"
#define 편집용량 16384
static unsigned char SMS[편집용량],पुर्ववत_डेटा[편집용량],복사자료[편집용량],मेजप_डेटा[1024];
static int लांबाय_मोल,INDEX_मोल,맨위,왼쪽,변경됨,रिगोवचें,पुर्ववत_लांबाय,위쪽,पुर्ववत_बदल,되돌림있음,इन्सटन्स_लांबाय,사용량,COLUMNS=68,ROW_COUNT=19;
static char फायल_प्रवेश_नांव[64],आदेश[128],FIND_प्रवेश[128];
