static int आदार_वर्ग,स्थिती_IMAGE,स्थिती_प्रतिक्षावळ;
static void 출력비우기(void){if(사용량){사용자호출(1,1,(uintptr_t)मेजप_डेटा,사용량,0,0,0);사용량=0;}}
static void बायट_डेटा(unsigned वर्ण_कोड){if(स्थिती_IMAGE){if((वर्ण_कोड&192)!=128){स्थिती_प्रतिक्षावळ+=वर्ण_कोड>=196?2:1;}if(स्थिती_प्रतिक्षावळ>=COLUMNS)return;}if(사용량==(int)sizeof(मेजप_डेटा))출력비우기();मेजप_डेटा[사용량++]=वर्ण_कोड;}
static void 글내보내기(const char *स्ट्रिंग_डेटा){while(*स्ट्रिंग_डेटा)बायट_डेटा((unsigned char)*स्ट्रिंग_डेटा++);}
static void 수치(unsigned आयटम_COUNT){char SECOND_मोल[12];int 순번=0;do{SECOND_मोल[순번++]='0'+आयटम_COUNT%10;आयटम_COUNT/=10;}while(आयटम_COUNT);while(순번)बायट_डेटा(SECOND_मोल[--순번]);}
static void हालोवचें_मोल(int ROW_स्थिती,int स्तंभ_स्थिती){글내보내기("\033[");수치(ROW_स्थिती);बायट_डेटा(';');수치(स्तंभ_स्थिती);बायट_डेटा('H');}
static int 이전항목(int डेटा_स्थिती){if(डेटा_स्थिती){डेटा_स्थिती--;while(डेटा_स्थिती>0&&(SMS[डेटा_स्थिती]&192)==128)डेटा_स्थिती--;}return डेटा_स्थिती;}
static int फुडलें_आयटम(int डेटा_स्थिती){if(डेटा_स्थिती<लांबाय_मोल){डेटा_स्थिती++;while(डेटा_स्थिती<लांबाय_मोल&&(SMS[डेटा_स्थिती]&192)==128)डेटा_स्थिती++;}return डेटा_स्थिती;}
static int चलोवप(int डेटा_स्थिती){while(डेटा_स्थिती>0&&SMS[डेटा_स्थिती-1]!='\n')डेटा_स्थिती--;return डेटा_स्थिती;}
static int सोपोवचें_ऑफसॅट(int डेटा_स्थिती){while(डेटा_स्थिती<लांबाय_मोल&&SMS[डेटा_स्थिती]!='\n')डेटा_स्थिती++;return डेटा_स्थिती;}
static int 너비(unsigned वर्ण_कोड){return वर्ण_कोड>=196?2:1;}
static int स्तंभ(int डेटा_स्थिती){int वर्ण_कोड=0;for(int 순번=चलोवप(डेटा_स्थिती);순번<डेटा_स्थिती;순번=फुडलें_आयटम(순번))वर्ण_कोड+=SMS[순번]=='\t'?4-वर्ण_कोड%4:너비(SMS[순번]);return वर्ण_कोड;}
static void तपासणीबिंदू(void){for(int 순번=0;순번<लांबाय_मोल;순번++)पुर्ववत_डेटा[순번]=SMS[순번];पुर्ववत_लांबाय=लांबाय_मोल;위쪽=INDEX_मोल;पुर्ववत_बदल=변경됨;되돌림있음=1;}
static void 바이트지우기(int 출발위치,int 도착위치){तपासणीबिंदू();for(int 순번=도착위치;순번<लांबाय_मोल;순번++)SMS[출발위치+순번-도착위치]=SMS[순번];लांबाय_मोल-=도착위치-출발위치;INDEX_मोल=출발위치;변경됨=1;}
static int 덧붙이기(const unsigned char *स्ट्रिंग_डेटा,int आयटम_COUNT){if(आयटम_COUNT>편집용량-लांबाय_मोल){알림문="File full (16384 bytes)";return 0;}तपासणीबिंदू();for(int 순번=लांबाय_मोल-1;순번>=INDEX_मोल;순번--)SMS[순번+आयटम_COUNT]=SMS[순번];for(int 순번=0;순번<आयटम_COUNT;순번++)SMS[INDEX_मोल+순번]=स्ट्रिंग_डेटा[순번];लांबाय_मोल+=आयटम_COUNT;INDEX_मोल+=आयटम_COUNT;변경됨=1;return 1;}
static void उबें(int 차이){int स्तंभ_स्थिती=स्तंभ(INDEX_मोल),डेटा_स्थिती=चलोवप(INDEX_मोल);if(차이<0){if(!डेटा_स्थिती)return;डेटा_स्थिती=चलोवप(डेटा_स्थिती-1);}else{डेटा_स्थिती=सोपोवचें_ऑफसॅट(डेटा_स्थिती);if(डेटा_स्थिती==लांबाय_मोल)return;डेटा_स्थिती++;}int वर्ण_कोड=0;while(डेटा_स्थिती<लांबाय_मोल&&SMS[डेटा_स्थिती]!='\n'&&वर्ण_कोड<स्तंभ_स्थिती){वर्ण_कोड+=SMS[डेटा_स्थिती]=='\t'?4-वर्ण_कोड%4:너비(SMS[डेटा_स्थिती]);डेटा_स्थिती=फुडलें_आयटम(डेटा_स्थिती);}INDEX_मोल=डेटा_स्थिती;}
static void 화면그리기(void){
    if(INDEX_मोल>लांबाय_मोल)INDEX_मोल=लांबाय_मोल;if(맨위>INDEX_मोल)맨위=चलोवप(INDEX_मोल);맨위=चलोवप(맨위);
    int ROW_स्थिती=0;for(int 순번=맨위;순번<INDEX_मोल;순번++)if(SMS[순번]=='\n')ROW_स्थिती++;
    while(ROW_स्थिती>=ROW_COUNT-1){맨위=सोपोवचें_ऑफसॅट(맨위);if(맨위<लांबाय_मोल)맨위++;ROW_स्थिती--;}
    int स्तंभ_स्थिती=स्तंभ(INDEX_मोल);if(स्तंभ_स्थिती<왼쪽)왼쪽=स्तंभ_स्थिती;if(स्तंभ_स्थिती-왼쪽>=COLUMNS-1)왼쪽=स्तंभ_स्थिती-COLUMNS+2;
    글내보내기("\033[?25l");int डेटा_स्थिती=맨위;
    for(int 반환값=0;반환값<ROW_COUNT-1;반환값++){
        हालोवचें_मोल(반환값+1,1);글내보내기("\033[0m\033[2K");int वर्ण_कोड=0,그려진상태=0;
        if(डेटा_स्थिती>=लांबाय_मोल&&반환값>ROW_स्थिती){글내보내기("\033[90m~\033[0m");continue;}
        while(डेटा_स्थिती<लांबाय_मोल&&SMS[डेटा_स्थिती]!='\n'){
            int फुडलें_ऑफसॅट=फुडलें_आयटम(डेटा_स्थिती),너비값=SMS[डेटा_स्थिती]=='\t'?4-वर्ण_कोड%4:너비(SMS[डेटा_स्थिती]);
            if(वर्ण_कोड>=왼쪽&&वर्ण_कोड-왼쪽+너비값<COLUMNS){
                if(SMS[डेटा_स्थिती]=='\t'){for(int 안쪽순번=0;안쪽순번<너비값;안쪽순번++)बायट_डेटा(' ');}else if(SMS[डेटा_स्थिती]<32||SMS[डेटा_स्थिती]==127){बायट_डेटा('?');}else for(int 안쪽순번=डेटा_स्थिती;안쪽순번<फुडलें_ऑफसॅट;안쪽순번++)बायट_डेटा(SMS[안쪽순번]);그려진상태+=너비값;
            }वर्ण_कोड+=너비값;डेटा_स्थिती=फुडलें_ऑफसॅट;
        }
        (void)그려진상태;if(डेटा_स्थिती<लांबाय_मोल)डेटा_स्थिती++;
    }
    हालोवचें_मोल(ROW_COUNT,1);글내보내기("\033[7m\033[2K");स्थिती_IMAGE=1;स्थिती_प्रतिक्षावळ=0;글내보내기(रिगोवचें?"INSERT ":"NORMAL ");
    int 이름바이트수=0;while(फायल_प्रवेश_नांव[이름바이트수]&&이름바이트수<30)बायट_डेटा(फायल_प्रवेश_नांव[이름바이트수++]);글내보내기(변경됨?" [+] ":" ");
    글내보내기("L");int रेग=1;for(int 순번=0;순번<INDEX_मोल;순번++)if(SMS[순번]=='\n')रेग++;수치(रेग);글내보내기(" ");
    // A second status is printed only when it fits; command/message is ASCII.
    if(알림문){int आयटम_COUNT=0;글내보내기(" | ");while(알림문[आयटम_COUNT]&&आयटम_COUNT<20)बायट_डेटा(알림문[आयटम_COUNT++]);}
    स्थिती_IMAGE=0;글내보내기("\033[0m");हालोवचें_मोल(ROW_स्थिती+1,स्तंभ_स्थिती-왼쪽+1);글내보내기("\033[?25h");출력비우기();
}
static int 누름값(void){
    if(अनिर्णित_की){int 셋째순번=अनिर्णित_की;अनिर्णित_की=0;return 셋째순번;}
    for(;;){
        int 셋째순번=사용자호출(16,1,0,0,0,0,0);
        unsigned आवाठ=사용자호출(16,3,0,0,0,0,0);
        if(COLUMNS!=(int)(आवाठ&65535)||ROW_COUNT!=(int)(आवाठ>>16)){
            COLUMNS=आवाठ&65535;ROW_COUNT=आवाठ>>16;화면그리기();
            if(आदार_वर्ग){हालोवचें_मोल(ROW_COUNT,1);글내보내기("\033[0m\033[2K");बायट_डेटा(आदार_वर्ग);글내보내기(आदेश);출력비우기();}
        }
        if(셋째순번>=0)return 셋째순번;
    }
}
static int 탈출됨(void){
    unsigned 현재위치=사용자호출(7,0,0,0,0,0,0);int 셋째순번=-1;
    while((unsigned)사용자호출(7,0,0,0,0,0,0)-현재위치<100){셋째순번=사용자호출(16,1,0,0,0,0,0);if(셋째순번>=0)break;}
    if(셋째순번<0)return 27;if(셋째순번!='['&&셋째순번!='O'){अनिर्णित_की=셋째순번;return 27;}
    int आयटम_COUNT=0;for(int 순번=0;순번<12;순번++){셋째순번=누름값();if(셋째순번>='0'&&셋째순번<='9'){आयटम_COUNT=आयटम_COUNT*10+셋째순번-'0';continue;}if(셋째순번=='A')return 1001;if(셋째순번=='B')return 1002;if(셋째순번=='C')return 1003;if(셋째순번=='D')return 1004;if(셋째순번=='H')return 1005;if(셋째순번=='F')return 1006;if(셋째순번=='~')return आयटम_COUNT==3?1007:आयटम_COUNT==5?1008:आयटम_COUNT==6?1009:आयटम_COUNT==1?1005:आयटम_COUNT==4?1006:27;return 27;}return 27;
}
static int Store_मोल(void){
    int फायल_हँडल=उगडचें_फायल(फायल_प्रवेश_नांव,वाचन_बरप|없으면만들기|내용비우기,0600);if(फायल_हँडल<0){알림문="Cannot open for save";return 0;}
    intptr_t आयटम_COUNT=बरोवचें_फायल_डेटा(फायल_हँडल,SMS,लांबाय_मोल);शेवट_फायल(फायल_हँडल);if(आयटम_COUNT!=लांबाय_मोल){알림문="Write failed";return 0;}변경됨=0;알림문="Saved (RAM)";return 1;
}
static int 같은지(const char *첫째값,const char *SECOND_मोल){while(*첫째값&&*첫째값==*SECOND_मोल){첫째값++;SECOND_मोल++;}return *첫째값==*SECOND_मोल;}
static void FIND_फुडलें(void){int आयटम_COUNT=0;while(FIND_प्रवेश[आयटम_COUNT])आयटम_COUNT++;if(!आयटम_COUNT){알림문="No search pattern";return;}for(int 순번=1;순번<=लांबाय_मोल;순번++){int डेटा_स्थिती=(INDEX_मोल+순번)%(लांबाय_मोल?लांबाय_मोल:1),안쪽순번=0;while(안쪽순번<आयटम_COUNT&&डेटा_स्थिती+안쪽순번<लांबाय_मोल&&SMS[डेटा_स्थिती+안쪽순번]==(unsigned char)FIND_प्रवेश[안쪽순번])안쪽순번++;if(안쪽순번==आयटम_COUNT){INDEX_मोल=डेटा_स्थिती;알림문="Match";return;}}알림문="Pattern not found";}
static int तत्पर(int वर्ग_मोल){
    int आयटम_COUNT=0;आदेश[0]=0;
    for(;;){हालोवचें_मोल(ROW_COUNT,1);글내보내기("\033[0m\033[2K");बायट_डेटा(वर्ग_मोल);글내보내기(आदेश);출력비우기();आदार_वर्ग=वर्ग_मोल;int 셋째순번=누름값();आदार_वर्ग=0;
        if(셋째순번==27||셋째순번==3)return 0;if(셋째순번==13||셋째순번==10)break;
        if(셋째순번==127||셋째순번==8){if(आयटम_COUNT){आयटम_COUNT--;while(आयटम_COUNT>0&&((unsigned char)आदेश[आयटम_COUNT]&192)==128)आयटम_COUNT--;आदेश[आयटम_COUNT]=0;}continue;}
        if(셋째순번>=32&&셋째순번<256&&आयटम_COUNT<120){आदेश[आयटम_COUNT++]=셋째순번;आदेश[आयटम_COUNT]=0;}
    }
    if(वर्ग_मोल=='/'){for(int 순번=0;순번<=आयटम_COUNT;순번++)FIND_प्रवेश[순번]=आदेश[순번];FIND_फुडलें();return 0;}
    if(같은지(आदेश,"q!"))return 1;
    if(같은지(आदेश,"q")){if(!변경됨)return 1;알림문="Unsaved: :w or :q!";return 0;}
    if(같은지(आदेश,"wq")||같은지(आदेश,"x"))return Store_मोल();
    if(같은지(आदेश,"w")){Store_मोल();return 0;}
    if(आदेश[0]=='w'&&आदेश[1]==' '){int 순번=2;while(आदेश[순번]==' ')순번++;int आवाठ=आयटम_COUNT-순번;if(आवाठ<1||आवाठ>63){알림문="Invalid file name";return 0;}for(int 안쪽순번=0;안쪽순번<आवाठ;안쪽순번++)फायल_प्रवेश_नांव[안쪽순번]=आदेश[순번+안쪽순번];फायल_प्रवेश_नांव[आवाठ]=0;Store_मोल();return 0;}
    int रेग=0;for(int 순번=0;순번<आयटम_COUNT;순번++){if(आदेश[순번]<'0'||आदेश[순번]>'9'){रेग=0;break;}रेग=रेग*10+आदेश[순번]-'0';if(रेग>16384){रेग=0;break;}}
    if(रेग){INDEX_मोल=0;while(--रेग&&INDEX_मोल<लांबाय_मोल){INDEX_मोल=सोपोवचें_ऑफसॅट(INDEX_मोल);if(INDEX_मोल<लांबाय_मोल)INDEX_मोल++;}return 0;}
    알림문="Unknown vi command";return 0;
}
